  str_season_maze_s2_help_title_702 = "幻珠エネルギー",
  str_season_maze_s2_help_title_703 = "幻珠レベル",
  str_season_maze_s2_help_title_704 = "幻珠の合成",
  str_season_maze_s2_help_title_705 = "幻珠の引き継ぎ",
  str_season_maze_s2_help_disc_101 = "過去の夢境に存在した不安定要素は、いまだ夢の領域に潜み、いつまた動き出すとも知れません。啓発者の助けを借りて再び夢境を訪れ、さまざまな探索を体験して、夢境での実力を養い、「終極の呑夢者」を撃退して夢境のエネルギーバランスを回復させましょう。",
  str_season_maze_s2_help_disc_102 = "啓発者と共に「夢占い札」の力を借りると、さまざまな「夢域」へと移動し、その「夢域」内のイベントを解放できます。探索の過程では、光霊の召喚、「夢境装備」や「幻珠」、その他各種の夢境資源の収集を通して、自身の力を向上させることができます。最後に「呑夢の暗影」と「終極の呑夢者」に見事挑戦できれば、夢境探索達成となり、豪華な報酬がもらえます。",
  str_season_maze_s2_help_disc_201 = "啓発者は夢境でのナビゲーターの行動を評価し、それに対応する「夢境ポイント」を記録していきます。「夢境ポイント」がたまると、対応する報酬がもらえます。",
  str_season_maze_s2_help_disc_202 = "探索が終了するたびに、啓発者は「夢境ランク」と「探索進行度」に基づいて「夢境ポイント」を記録します。累積「夢境ポイント」が相応のポジションに達すると、対応する報酬がもらえます。また、「夢境任務」を達成すると、追加で「夢境ポイント」を獲得できます。",
  str_season_maze_s2_help_disc_203 = "累積「夢境ポイント」が相応のポジションに達すると、対応する報酬がもらえます。一定時間ごとに、さらに多くの報酬ポジションが解放されます。",
  str_season_maze_s2_help_disc_204 = "夢境の中にはさまざまな「夢境任務」が用意されており、任務を達成すると、追加で「夢境ポイント」を獲得できます。",
  str_season_maze_s2_help_disc_301 = "夢境はいくつかのランクに分かれています。ランクが高いほど、挑戦難易度は高くなり、挑戦成功後に獲得できる「夢境ポイント」も多くなります。夢境ランク画面では、そのランクで遭遇する「終極の呑夢者」を確認できます。「終極の呑夢者」の情報に基づき、探索の戦略を練りましょう。",
  str_season_maze_s2_help_disc_302 = "夢境ランクは「ランク1」から始まり、前のランクをクリア後、次のランクが解放されます。一部のランクは時間の経過に伴い解放されます。「ランク3」が解放されると、同時に「幻珠」システムが解放され、探索の一助とすることができます。",
  str_season_maze_s2_help_disc_303 = "夢境に入る時は、初期編成に必ず4名の光霊を選択し、探索を開始してください。編成された光霊は夢境外での突破レベルを継承しますが、その他の育成ステータスやレベルは継承しません。",
  str_season_maze_s2_help_disc_304 = "一部の光霊は「夢境の残響」で使用禁止となります。使用禁止となった光霊は探索中に召喚できません。「夢境の残響」では毎期、使用禁止となる光霊が変更されます。",
  str_season_maze_s2_help_disc_401 = "探索過程では、ナビゲーターは自身を操作し、啓発者を連れて探索を行うことができます。",
  str_season_maze_s2_help_disc_402 = "啓発者は夢境のエネルギーの変化に基づき、夢境をいくつかの異なる「夢域」に分割します。ナビゲーターは「夢域」間を行き来し、各「夢域」でそれぞれ異なるイベントを解放します。",
  str_season_maze_s2_help_disc_403 = "ナビゲーターは「夢占い札」の力を借り、異なる夢域間を移動できます。「夢占い札」の「行動歩数」によって、移動できる「夢域」の数が決まり、一部の「夢占い札」には追加の資源、または特殊効果がついています。毎ターン開始時、啓発者はカードストレージの中から一定数の「夢占い札」を取り出します。ナビゲーターはそのうちの1枚を選んで出すか、画面までドラッグして「夢占い札」の効果を実行します。",
  str_season_maze_s2_help_disc_404 = "夢境の中では、さまざまな資源を獲得できます。「夢の金貨」は各種アイテムを購入するのに使え、「夢境経験値」は「夢境ランク」を上げることができます。また、「夢の利息」は毎ターン獲得できる「夢の金貨」の数を増やし、「ターン」はナビゲーターの夢境での安全と安定を守ってくれます。",
  str_season_maze_s2_help_disc_405 = "「ポーチ」では、今回の探索過程で編成した光霊、獲得済みの「夢境装備」およびカードストレージに収納済みの「夢占い札」を確認できます。",
  str_season_maze_s2_help_disc_406 = "夢境の元の主が残した記憶と感情は、何層もの夢境のエネルギーに包まれ、「幻珠」となっています。ここでは、今回の探索で獲得できる「幻珠」を確認でき、装備や合成などの操作も行えます。",
  str_season_maze_s2_help_disc_407 = "「呑夢の暗影」は一定ターン後、ナビゲーターに奇襲を仕掛けてきます。「呑夢の暗影」に勝たなければ、夢境探索を続けることはできません。「終極の呑夢者」は最後の「呑夢の暗影」で、「終極の呑夢者」に勝つと、その回の探索は終了します。夢境ランクと探索進行度にもとづき、「夢境ポイント」を獲得できます。",
  str_season_maze_s2_help_disc_408 = "ここでは、今回の戦場特性と敵情報を確認できます。ナビゲーターはこれらの情報にもとづき、戦略を調整することができます。挑戦に見事成功すると、対応する報酬を獲得でき、失敗した場合は「ターン」を消費して再度挑戦することができます。",
  str_season_maze_s2_help_disc_409 = "探索過程で獲得した「夢境経験値」で「夢境ランク」を上げることができます。「夢境ランク」が上がると、光霊のレベル、装備レベルが上がり、新たに「夢占い札」と「ドリーマーアイテム」を獲得して夢境探索の一助とすることができます。",
  str_season_maze_s2_help_disc_501 = "「危険夢域」に入り、敵と交戦し、勝利した後、「夢境装備」を1つ獲得できます。",
  str_season_maze_s2_help_disc_502 = "「未知夢域」に入ると、ランダムイベントが解放されます。一部イベントは「夢占い札」3枚を選び、点数の合計の大きさを判定する必要があり、判定成功後、対応する報酬を獲得できます。",
  str_season_maze_s2_help_disc_503 = "「資源夢域」に入ると、「夢の金貨」、「夢の経験値」、「幻珠」など、対応するタイプの資源報酬を獲得できます。この「夢域」に入るまでの「行動歩数」が多いほど、報酬も豪華になります。",
  str_season_maze_s2_help_disc_504 = "「未開拓夢域」に入ると、光霊を派遣して任務を実行し、持続効果を獲得することができます。派遣期間中、その光霊は戦闘に参加できず、5ターン経過後、自動的に帰隊します。",
  str_season_maze_s2_help_disc_505 = "「秘宝夢域」に入ると、各種報酬の中から、1種類を選択して獲得できます。",
  str_season_maze_s2_help_disc_506 = "「夢域トンネル」に入ると、「呑夢の暗影」の襲来を1ターン遅らせることができます。",
  str_season_maze_s2_help_disc_507 = "「空白夢域」に入ると、いかなる効果も発動しません。",
  str_season_maze_s2_help_disc_508 = "「占夢夢域」では、「夢の金貨」を消費して、現在持っている「夢占い札」をリセット、または削除できます。",
  str_season_maze_s2_help_disc_509 = "「流通夢域」では、他のプレイヤーとさまざまなタイプの「幻珠」を交換できます。",
  str_season_maze_s2_help_disc_510 = "「安全夢域」では、休養、調整ができます。光霊の召喚、アイテムの代理購入、薬の購入、光霊の復活などを行い、実力を強化します。また、「夢の金貨」を「夢熔炉」に投入すれば、その後の挑戦でより多くの強力なアイテムを解放できます。",
  str_season_maze_s2_help_disc_511 = "「転送夢域」に入ると、それに対応する「転送夢域」に直接転送され、他の夢域を経由することはありません。転送は一方通行ですのでご注意ください。",
  str_season_maze_s2_help_disc_512 = "「購買夢域」では「夢境装備」を購入できます。",
  str_season_maze_s2_help_disc_513 = "「召喚夢域」に入ると、属性を一つ選び、その属性に限定して光霊を召喚できます。いったん属性を選択すると、今回の召喚で他の属性には変更できませんので、ご注意ください。",
  str_season_maze_s2_help_disc_601 = "ナビゲーターは光霊を編成できます。編成した光霊は夢境外での突破レベルを引き継ぎますが、その他の育成ステータスやレベルは継承しません。「夢境ランク」を上げると、夢境の中の光霊のレベルや装備レベルが上がります。",
  str_season_maze_s2_help_disc_602 = "「夢境装備」は長い時の流れの中で、夢境を勇敢に探険したドリーマーたちが残した貴重な知識と遺物です。「夢境装備」はさまざまな効果を発動でき、ナビゲーターの夢境探索を助けてくれます。",
  str_season_maze_s2_help_disc_603 = "ナビゲーターは「夢占い札」の力を借り、異なる夢域間を移動できます。「夢占い札」の「行動歩数」によって、移動できる「夢域」の数が決まり、一部の「夢占い札」には追加の資源、または特殊効果がついています。「夢の金貨」、「夢の利息」、「夢境経験値」、「ターン」などを含みますが、これに限られません。",
  str_season_maze_s2_help_disc_604 = "夢境の元の主が残した記憶と感情は、何層もの夢境のエネルギーに包まれ、「幻珠」となっています。「幻珠」は夢境でのナビゲーターの戦闘力を上げることができるので、「呑夢の暗影」が拾ってしまわないよう気を付けましょう！",
  str_season_maze_s2_help_disc_605 = "「ドリーマーアイテム」は夢境のエネルギーが夢境のモノに対する「記憶」に宿り、偶然風化して出来たものです。「ドリーマーアイテム」はそれぞれ異なる効果を持っており、時機を見極め、うまく使用すれば、探索の助けになります。",
  str_season_maze_s2_help_disc_701 = "「幻珠」は技珠、強化珠、充填珠の3タイプに分かれています。技珠は戦闘中に実際に発動できる技で、強化珠は装備済みの他の幻珠を強化し、充填珠は戦闘中のエネルギー獲得を加速させます。",
  str_season_maze_s2_help_disc_702 = "戦闘中、光霊が連鎖で1マス移動するごとに、「幻珠」エネルギーを1獲得します。連鎖終了後、プレイヤーの累積エネルギーが「幻珠」の必要エネルギーよりも多かった場合、左から右へ順番に「幻珠」の技が発動します。",
  str_season_maze_s2_help_disc_703 = "「幻珠」には4つのレベルがあり、★3が最高です。レベルが高いほど、高い効果を持っています。",
  str_season_maze_s2_help_disc_704 = "同じレベルの「幻珠」を2つ合成すると、1つ上のレベルの「幻珠」が1つできます。合成する2つの「幻珠」の名称が同じであれば、必ず同名の「幻珠」ができます。2つの「幻珠」タイプが同じであれば、必ず同タイプの「幻珠」ができます。2つの「幻珠」タイプが異なる場合は、ランダムに「幻珠」が1つできます。",
  str_season_maze_s2_help_disc_705 = "毎回の「夢境の残響」挑戦終了時、装備済みの最もレベルの高い「幻珠」5つを次の挑戦に引き継ぎます。装備済みの「幻珠」の数が足りない場合、バッグの中のレベルの最も高い「幻珠」を引き継ぎます。引き継いだ「幻珠」のレベルは1にリセットされます。",
  str_season_maze_s2_guide_warn_90020101 = "ヒント：夢境が交錯する空間に到着しました。啓発者の導きに従い実力を強化して、「終極の呑夢者」を倒しましょう。",
  str_season_maze_s2_guide_warn_90020102 = "ヒント：ここをタップすると、探索を開始します。",
  str_season_maze_s2_guide_warn_90020201 = "ヒント：探索が終了するたびに、評価に基づいて「夢境ポイント」を獲得します。累積「夢境ポイント」が対応するランクに達すると、探索報酬がもらえます。",
  str_season_maze_s2_guide_warn_90020202 = "ヒント：「呑夢者」を倒して「夢境任務」を達成すると「夢境ポイント」を獲得できます。",
  str_season_maze_s2_guide_warn_90020203 = "ヒント：報酬ランクは時間の経過につれて順次開放されます。現在の報酬をすべて受け取ると、次のランク開放までの時間を確認できます。",
  str_season_maze_s2_guide_warn_90020301 = "ヒント：夢境はいくつかのランクに分かれています。ランクが高いほど、難易度も高くなり、挑戦に成功した後獲得できる「夢境ポイント」も多くなります。現在のランクをクリアして初めて、次のランクに挑戦できます。一部のランクは一定時間経過後に順次開放されます。",
  str_season_maze_s2_guide_warn_90020302 = "状況を分析しています…この夢境の中で破壊行為を働く「終極の呑夢者」の存在を検知しました。「終極の呑夢者」をタップすると、さらに詳しい情報を確認できます。",
